{
  "domain": "Turkish",
  "description": "Turkish core building blocks and conversation words for A2–B1 learners, Standard Turkish (Istanbul norm).",
  "terms": [
    {
      "term": "var",
      "category": "Building block",
      "definition": "Says something exists, or that someone has it; Turkish uses it instead of a 'have' verb.",
      "example": "Köşede bir eczane var. — There's a pharmacy on the corner.",
      "anti_example": "Not 'Bir arabaya sahibim' for 'I have a car': say 'Arabam var'."
    },
    {
      "term": "mı / mi / mu / mü",
      "category": "Particle",
      "definition": "Turns a statement into a yes/no question. Its vowel matches the last vowel of the word before it.",
      "example": "Otobüs Kadıköy'e gider mi? — Does the bus go to Kadıköy?",
      "discussion": "Write it as a separate word. With 'you', the person ending moves onto it: Geliyor musun?"
    },
    {
      "term": "-mak / -mek istemek",
      "category": "Pattern",
      "definition": "Put a verb's dictionary form before istemek to say you want to do it.",
      "example": "Akşam sinemaya gitmek istiyorum. — I want to go to the cinema tonight.",
      "anti_example": "Not 'İstiyorum gitmek': the verb you want comes first and istemek goes last. Say 'Gitmek istiyorum'."
    },
    {
      "term": "yani",
      "category": "Conversation word",
      "definition": "Means 'I mean' or 'so': you use it to explain again or to sum up.",
      "example": "Çok yorgunum, yani gelmiyorum. — I'm really tired, so I'm not coming.",
      "discussion": "Also a filler while you think, like English 'well'. Used a lot, it sounds very casual."
    },
    {
      "term": "değil",
      "category": "Building block",
      "definition": "Negates a noun or adjective: 'is not', 'am not'. Verbs take -me / -ma instead.",
      "example": "Bu çorba sıcak değil. — This soup isn't hot.",
      "anti_example": "Not 'Çorba sıcak yok' for 'The soup isn't hot': yok means 'there is none'. Say 'Çorba sıcak değil'."
    },
    {
      "term": "gibi",
      "category": "Particle",
      "definition": "Compares: 'like' or 'as', placed after the noun you compare to.",
      "example": "Kardeşim bir kedi gibi uyuyor. — My brother sleeps like a cat.",
      "discussion": "After ben and sen, say benim gibi and senin gibi, not ben gibi."
    },
    {
      "term": "-abilmek / -ebilmek",
      "category": "Pattern",
      "definition": "Attaches 'can' to a verb stem: gel- becomes gelebil-, then the normal ending follows.",
      "example": "Pencereyi açabilir misin? — Can you open the window?",
      "anti_example": "Not 'gelebilmiyorum' for 'I can't come': the negative drops -bil-. Say 'gelemiyorum'."
    },
    {
      "term": "yok",
      "category": "Building block",
      "definition": "Says something isn't there, or that you don't have it: the other half of var.",
      "example": "Maalesef bugün simit yok. — Sorry, no simit today.",
      "discussion": "Answer a 'var mı?' question with a bare 'yok'. It sounds more natural than 'hayır'."
    },
    {
      "term": "bence",
      "category": "Conversation word",
      "definition": "Gives your opinion: 'I think', 'in my view'. It usually opens the sentence.",
      "example": "Bence bu elbise çok güzel. — I think this dress is really nice.",
      "anti_example": "Not 'Düşünüyorum ki elbise güzel' for 'I think the dress is nice': say 'Bence elbise güzel'."
    },
    {
      "term": "lazım",
      "category": "Building block",
      "definition": "Means 'needed'. Give the verb a 'my' or 'your' ending first to say you have to: gitmem lazım.",
      "example": "Artık gitmem lazım. — I have to go now.",
      "discussion": "For a thing you need, just add lazım: Bana su lazım (I need water). Very common in speech."
    }
  ],
  "relationships": [
    {
      "source": "değil",
      "target": "yok",
      "relationship_type": "often confused with",
      "description": "Both translate as 'not' in English, but değil negates a description and yok says something isn't there."
    }
  ]
